<?php
declare(strict_types=1);
namespace KMM\Core;

/** New-install schema v7. Existing installations need a separately verified migration. */
final class MessageSchema {
    public static function statements(): array { return [
        "CREATE TABLE IF NOT EXISTS messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kind VARCHAR(32) NOT NULL,sender_user_id BIGINT UNSIGNED NULL,subject VARCHAR(80) NOT NULL DEFAULT '',body TEXT NOT NULL,reply_to_id BIGINT UNSIGNED NULL,system_event_key VARCHAR(100) NULL UNIQUE,moderation_state VARCHAR(20) NOT NULL DEFAULT 'active',sender_deleted_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_msg_sender(sender_user_id,created_at),INDEX idx_msg_created(created_at),CONSTRAINT fk_message_sender FOREIGN KEY(sender_user_id) REFERENCES users(id),CONSTRAINT fk_message_reply FOREIGN KEY(reply_to_id) REFERENCES messages(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS message_recipients (message_id BIGINT UNSIGNED NOT NULL,recipient_user_id BIGINT UNSIGNED NOT NULL,read_at DATETIME NULL,trashed_at DATETIME NULL,purged_at DATETIME NULL,starred_at DATETIME NULL,delivered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,revision INT UNSIGNED NOT NULL DEFAULT 1,PRIMARY KEY(message_id,recipient_user_id),INDEX idx_recipient_inbox(recipient_user_id,purged_at,trashed_at,message_id),INDEX idx_recipient_unread(recipient_user_id,purged_at,trashed_at,read_at),CONSTRAINT fk_mr_message FOREIGN KEY(message_id) REFERENCES messages(id),CONSTRAINT fk_mr_user FOREIGN KEY(recipient_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS message_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,message_id BIGINT UNSIGNED NOT NULL,reporter_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(800) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'open',reviewer_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,UNIQUE KEY uniq_report(message_id,reporter_id),INDEX idx_reports_status(status,created_at),CONSTRAINT fk_report_message FOREIGN KEY(message_id) REFERENCES messages(id),CONSTRAINT fk_report_user FOREIGN KEY(reporter_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS message_user_settings (user_id BIGINT UNSIGNED PRIMARY KEY,allow_direct TINYINT(1) NOT NULL DEFAULT 1,public_profile TINYINT(1) NOT NULL DEFAULT 0,notify_email TINYINT(1) NOT NULL DEFAULT 0,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_message_settings_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS message_blocks (user_id BIGINT UNSIGNED NOT NULL,blocked_user_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,blocked_user_id),CONSTRAINT fk_blocks_user FOREIGN KEY(user_id) REFERENCES users(id),CONSTRAINT fk_blocks_target FOREIGN KEY(blocked_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS message_broadcasts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,message_id BIGINT UNSIGNED NOT NULL UNIQUE,event_key VARCHAR(100) NOT NULL UNIQUE,state VARCHAR(24) NOT NULL DEFAULT 'queued',cursor_user_id BIGINT UNSIGNED NOT NULL DEFAULT 0,delivered_count INT UNSIGNED NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at DATETIME NULL,INDEX idx_broadcast_state(state,id),CONSTRAINT fk_broadcast_message FOREIGN KEY(message_id) REFERENCES messages(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS message_delivery_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,broadcast_id BIGINT UNSIGNED NOT NULL,recipient_user_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'delivered',attempts INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_broadcast_recipient(broadcast_id,recipient_user_id),INDEX idx_delivery_status(status,created_at),CONSTRAINT fk_delivery_broadcast FOREIGN KEY(broadcast_id) REFERENCES message_broadcasts(id),CONSTRAINT fk_delivery_user FOREIGN KEY(recipient_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
    ]; }
}
